  <div class="board" id="board"></div>
  <div class="status-bar" id="statusBar">
    <span class="status-dot connecting" id="statusDot"></span>
    <span id="statusText">Connecting...</span>
  </div>
  <script type="module" src="/src/main.js"></script>
