    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #5aac44;
    }

    .status-dot.disconnected {
      background: #ff5630;
    }

    .status-dot.connecting {
      background: #ffab00;
    }
  </style>
</head>
