      display: flex;
      gap: 12px;
      padding: 20px;
      overflow-x: auto;
      min-height: 100vh;
      align-items: flex-start;
    }

    .column {
      background: #ebecf0;
      border-radius: 8px;
      min-width: 280px;
      max-width: 280px;
      padding: 10px;
      display: flex;
      flex-direction: column;
      max-height: calc(100vh - 40px);
    }

