    .add-card-input:focus {
      border-color: #0079bf;
    }

    .add-card-btn {
      margin-top: 6px;
      padding: 6px 12px;
      background: #0079bf;
      color: white;
      border: none;
      border-radius: 4px;
      font-size: 13px;
      cursor: pointer;
      font-family: inherit;
    }

    .add-card-btn:hover {
