{"content": "// --- State ---
let boardState = [];
let sse = null;
let reconnectTimer = null;

// --- API ---
const API_BASE = (import.meta.env.VITE_API_URL || '') || '';

async function fetchBoard() {
  const res = await fetch(`${API_BASE}/api/board`);
  if (!res.ok) throw new Error('Failed to fetch board');
  return res.json();
}

async function createCard(columnId, text) {
  const res = await fetch(`${API_BASE}/api/cards`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ column_id: columnId, text })
  });
  if (!res.ok) throw new Error('Failed to create card');
  return res.json();
}

async function moveCard(cardId, columnId, beforeId, afterId) {
  const res = await fetch(`${API_BASE}/api/cards/${cardId}/move`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ column_id: columnId, before_id: beforeId, after_id: afterId })
  });
  if (!res.ok) throw new Error('Failed to move card');
  return res.json();
}

async function deleteCard(cardId) {
  const res = await fetch(`${API_BASE}/api/cards/${cardId}`, {
    method: 'DELETE'
  });
  if (!res.ok) throw new Error('Failed to delete card');
  return res.json();
}

// --- Rendering ---
const boardEl = document.getElementById('board');
const statusDot = document.getElementById('statusDot');
const statusText = document.getElementById('statusText');

function setStatus(status, text) {
  statusDot.className = `status-dot ${status}`;
  statusText.textContent = text;
}

function renderBoard() {
  boardEl.innerHTML = '';

  for (const column of boardState) {
    const columnEl = createColumnElement(column);
    boardEl.appendChild(columnEl);
  }
}

function createColumnElement(column) {
  const colEl = document.createElement('div');
  colEl.className = 'column';
  colEl.dataset.columnId = column.id;

  // Header
  const header = document.createElement('div');
  header.className = 'column-header';
  header.innerHTML = `
    <span>${escapeHtml(column.title)}</span>
    <span class="card-count">${column.cards.length}</span>
  `;
  colEl.appendChild(header);

  // Cards list
  const cardsList = document.createElement('div');
  cardsList.className = 'cards-list';
  cardsList.dataset.columnId = column.id;

  for (const card of column.cards) {
    cardsList.appendChild(createCardElement(card));
  }

  colEl.appendChild(cardsList);

  // Add card form
  const form = document.createElement('div');
  form.className = 'add-card-form';
  form.innerHTML = `
    <textarea class="add-card-input" placeholder="Enter a title for this card..." rows="1"></textarea>
    <button class="add-card-btn">Add a card</button>
    <div class="add-card-cancel">Press ESC to cancel</div>
  `;
  colEl.appendChild(form);

  // Form handlers
  const input = form.querySelector('.add-card-input');
  const addBtn = form.querySelector('.add-card-btn');
  const cancelBtn = form.querySelector('.add-card-cancel');

  addBtn.addEventListener('click', () => {
    const text = input.value.trim();
    if (text) {
      handleCreateCard(column.id, text, cardsList, input);
    }
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      const text = input.value.trim();
      if (text) {
        handleCreateCard(column.id, text, cardsList, input);
      }
    }
    if (e.key === 'Escape') {
      input.value = '';
      input.blur();
    }
  });

  input.addEventListener('focus', () => {
    addBtn.textContent = 'Save';
    cancelBtn.style.display = 'block';
  });

  input.addEventListener('blur', () => {
    if (!input.value.trim()) {
      addBtn.textContent = 'Add a card';
      cancelBtn.style.display = 'none';
    }
  });

  cancelBtn.addEventListener('click', () => {
    input.value = '';
    input.blur();
  });

  return colEl;
}

function createCardElement(card) {
  const cardEl = document.createElement('div');
  cardEl.className = 'card';
  cardEl.dataset.cardId = card.id;
  cardEl.dataset.position = card.position;
  cardEl.draggable = true;
  cardEl.textContent = card.text;

  // Drag events
  cardEl.addEventListener('dragstart', handleDragStart);
  cardEl.addEventListener('dragend', handleDragEnd);

  return cardEl;
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// --- Card Creation ---
async function handleCreateCard(columnId, text, cardsList, input) {
  // Optimistic: create card element immediately
  const tempId = 'temp-' + Date.now();
  const cardEl = createCardElement({ id: tempId, text, position: Infinity });
  cardEl.classList.add('dragging'); // Show as being added
  cardsList.appendChild(cardEl);

  try {
    const card = await createCard(columnId, text);
    // Replace optimistic element with server-authoritative
    cardEl.remove();
    const newCardEl = createCardElement(card);
    cardsList.appendChild(newCardEl);
    updateColumnCount(columnId);
  } catch (err) {
    console.error('Failed to create card:', err);
    cardEl.remove();
    // Could show error toast here
  }

  input.value = '';
  input.focus();
}

// --- Drag and Drop ---
let draggedCardId = null;
let draggedCardEl = null;
let placeholder = null;

function handleDragStart(e) {
  draggedCardId = e.currentTarget.dataset.cardId;
  draggedCardEl = e.currentTarget;
  draggedCardEl.classList.add('dragging');

  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', draggedCardId);

  // Create placeholder
  placeholder = document.createElement('div');
  placeholder.className = 'drop-placeholder';
}

function handleDragEnd(e) {
  e.currentTarget.classList.remove('dragging');
  draggedCardId = null;
  draggedCardEl = null;

  // Remove placeholder
  if (placeholder && placeholder.parentNode) {
    placeholder.parentNode.removeChild(placeholder);
  }
  placeholder = null;

  // Remove drop indicators from all cards
  document.querySelectorAll('.card').forEach(c => {
    c.classList.remove('drop-above', 'drop-below');
  });
}

// Set up drop zones on the board
boardEl.addEventListener('dragover', (e) => {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';

  if (!draggedCardEl) return;

  const cardEls = [...document.querySelectorAll('.card:not(.dragging)')];
  const target = getClosestCard(cardEls, e.clientY);

  // Remove all indicators
  cardEls.forEach(c => c.classList.remove('drop-above', 'drop-below'));

  if (target) {
    const rect = target.getBoundingClientRect();
    const midY = rect.top + rect.height / 2;
    if (e.clientY < midY) {
      target.classList.add('drop-above');
    } else {
      target.classList.add('drop-below');
    }
  }

  // Move placeholder
  if (placeholder) {
    const cardsList = findCardsListForDrop(e.target);
    if (cardsList) {
      if (target) {
        const rect = target.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        if (e.clientY < midY) {
          cardsList.insertBefore(placeholder, target);
        } else {
          cardsList.insertBefore(placeholder, target.nextSibling);
        }
      } else {
        cardsList.appendChild(placeholder);
      }
    }
  }
});

boardEl.addEventListener('drop', async (e) => {
  e.preventDefault();

  if (!draggedCardId) return;

  const cardEls = [...document.querySelectorAll('.card:not(.dragging)')];
  const target = getClosestCard(cardEls, e.clientY);
  const cardsList = findCardsListForDrop(e.target);

  if (!cardsList) return;

  const targetColumnId = cardsList.dataset.columnId;

  // Calculate before and after IDs
  let beforeId = null;
  let afterId = null;

  if (target) {
    const rect = target.getBoundingClientRect();
    const midY = rect.top + rect.height / 2;
    if (e.clientY < midY) {
      // Insert before target
      beforeId = target.dataset.cardId;
      // Get the card after target (previous sibling)
      const prevCard = target.previousElementSibling;
      if (prevCard && prevCard.classList.contains('card')) {
        afterId = prevCard.dataset.cardId;
      }
    } else {
      // Insert after target
      afterId = target.dataset.cardId;
      // Get the card after target (next sibling)
      const nextCard = target.nextElementSibling;
      if (nextCard && nextCard.classList.contains('card')) {
        beforeId = nextCard.dataset.cardId;
      }
    }
  }

  // Optimistic UI update: move the card in the DOM
  const cardEl = document.querySelector(`.card[data-card-id="${draggedCardId}"]`);
  if (cardEl) {
    cardEl.classList.remove('dragging');

    // Remove from old position
    cardEl.remove();

    // Insert at new position
    if (placeholder && placeholder.parentNode === cardsList) {
      cardsList.insertBefore(cardEl, placeholder);
    } else {
      cardsList.appendChild(cardEl);
    }

    // Update column counts
    updateAllColumnCounts();
  }

  // Send to server
  try {
    const serverCard = await moveCard(draggedCardId, targetColumnId, beforeId, afterId);
    // Reconcile: update position data
    if (cardEl) {
      cardEl.dataset.position = serverCard.position;
    }
  } catch (err) {
    console.error('Failed to move card:', err);
    // On failure, the server will broadcast the correct state via SSE
    // which will reconcile the DOM
  }

  draggedCardId = null;
  draggedCardEl = null;
});

function getClosestCard(cardEls, y) {
  let closest = null;
  let closestDist = Infinity;

  for (const card of cardEls) {
    const rect = card.getBoundingClientRect();
    const midY = rect.top + rect.height / 2;
    const dist = Math.abs(y - midY);
    if (dist < closestDist) {
      closestDist = dist;
      closest = card;
    }
  }

  return closest;
}

function findCardsListForDrop(target) {
  const el = target.closest('.cards-list');
  if (el) return el;

  // Try to find a cards-list in the column
  const column = target.closest('.column');
  if (column) {
    return column.querySelector('.cards-list');
  }

  return null;
}

function updateColumnCount(columnId) {
  const colEl = document.querySelector(`.column[data-column-id="${columnId}"]`);
  if (colEl) {
    const count = colEl.querySelectorAll('.card').length;
    const countEl = colEl.querySelector('.card-count');
    if (countEl) countEl.textContent = count;
  }
}

function updateAllColumnCounts() {
  document.querySelectorAll('.column').forEach(col => {
    const count = col.querySelectorAll('.card').length;
    const countEl = col.querySelector('.card-count');
    if (countEl) countEl.textContent = count;
  });
}

// --- SSE Connection ---
function connectSSE() {
  if (sse) {
    sse.close();
  }

  setStatus('connecting', 'Connecting...');

  sse = new EventSource(`${API_BASE}/api/stream`);

  sse.onopen = () => {
    setStatus('connected', 'Connected');
    if (reconnectTimer) {
      clearTimeout(reconnectTimer);
      reconnectTimer = null;
    }
  };

  sse.onerror = () => {
    setStatus('disconnected', 'Disconnected - reconnecting...');
    // EventSource will auto-reconnect, but we track it
    reconnectTimer = setTimeout(connectSSE, 3000);
  };

  // Handle create events
  sse.addEventListener('create', (e) => {
    const data = JSON.parse(e.data);
    const { card, columnId } = data;

    const cardsList = document.querySelector(`.cards-list[data-column-id="${columnId}"]`);
    if (!cardsList) return;

    // Check if card already exists (avoid duplicates)
    const existing = document.querySelector(`.card[data-card-id="${card.id}"]`);
    if (existing) {
      // Move it to correct position
      existing.remove();
    }

    const cardEl = createCardElement(card);
    cardsList.appendChild(cardEl);
    updateColumnCount(columnId);
  });

  // Handle move events
  sse.addEventListener('move', (e) => {
    const data = JSON.parse(e.data);
    const { card, columnId, oldColumnId } = data;

    // Remove card from old position
    const cardEl = document.querySelector(`.card[data-card-id="${card.id}"]`);

    if (cardEl) {
      cardEl.remove();
    }

    // Add card to new column at correct position
    const targetCardsList = document.querySelector(`.cards-list[data-column-id="${columnId}"]`);
    if (!targetCardsList) return;

    // Rebuild the cards list to ensure correct order
    // This is the reconciliation step
    reconcileColumn(columnId);
    if (oldColumnId && oldColumnId !== columnId) {
      reconcileColumn(oldColumnId);
    }
  });

  // Handle delete events
  sse.addEventListener('delete', (e) => {
    const data = JSON.parse(e.data);
    const { cardId, columnId } = data;

    const cardEl = document.querySelector(`.card[data-card-id="${cardId}"]`);
    if (cardEl) {
      cardEl.remove();
      updateColumnCount(columnId);
    }
  });

  // Handle renormalize events
  sse.addEventListener('renormalize', (e) => {
    const data = JSON.parse(e.data);
    const { columnId, cards } = data;

    const cardsList = document.querySelector(`.cards-list[data-column-id="${columnId}"]`);
    if (!cardsList) return;

    // Rebuild the cards list with authoritative order
    cardsList.innerHTML = '';
    for (const card of cards) {
      cardsList.appendChild(createCardElement(card));
    }
    updateColumnCount(columnId);
  });
}

// Reconcile a column's cards with server state
async function reconcileColumn(columnId) {
  try {
    const board = await fetchBoard();
    const column = board.find(c => c.id === columnId);
    if (!column) return;

    const cardsList = document.querySelector(`.cards-list[data-column-id="${columnId}"]`);
    if (!cardsList) return;

    // Check if there's a dragged card that hasn't been reconciled yet
    const cardEls = [...cardsList.querySelectorAll('.card')];
    const cardIds = cardEls.map(el => el.dataset.cardId);
    const serverCardIds = column.cards.map(c => c.id);

    // If the sets match, just reorder
    if (cardIds.length === serverCardIds.length &&
        cardIds.every(id => serverCardIds.includes(id))) {
      // Reorder DOM to match server
      cardsList.innerHTML = '';
      for (const card of column.cards) {
        cardsList.appendChild(createCardElement(card));
      }
    } else {
      // Full rebuild - server state is authoritative
      cardsList.innerHTML = '';
      for (const card of column.cards) {
        cardsList.appendChild(createCardElement(card));
      }
    }

    updateColumnCount(columnId);
  } catch (err) {
    console.error('Failed to reconcile column:', err);
  }
}

// --- Initialization ---
async function init() {
  try {
    boardState = await fetchBoard();
    renderBoard();
    connectSSE();
  } catch (err) {
    console.error('Failed to initialize:', err);
    setStatus('disconnected', 'Failed to load board');
  }
}

init();
