    .card {
      background: white;
      border-radius: 6px;
      padding: 8px 12px;
      box-shadow: 0 1px 2px rgba(0,0,0,0.15);
      cursor: grab;
      font-size: 14px;
      line-height: 1.4;
      word-break: break-word;
      position: relative;
      transition: opacity 0.15s, transform 0.15s;
    }

    .card:hover {
      background: #f4f5f7;
    }

    .card.dragging {
      opacity: 0.5;
