      gap: 12px;
      padding: 20px;
      overflow-x: auto;
      min-height: 100vh;
      align-items: flex-start;
    }

    .column {
      background: #ebecf0;
      border-radius: 8px;
      min-width: 280px;
      max-width: 280px;
      padding: 10px;
      display: flex;
      flex-direction: column;
      max-height: calc(100vh - 40px);
    }

    .column-header {
      font-weight: 600;
      font-size: 14px;
      padding: 6px 8px;
      margin-bottom: 8px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .column-header .card-count {
      background: rgba(0,0,0,0.1);
      border-radius: 10px;
      padding: 2px 8px;
      font-size: 12px;
      font-weight: normal;
    }

    .cards-list {
      flex: 1;
      overflow-y: auto;
      min-height: 40px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 2px;
    }

    .card {
      background: white;
      border-radius: 6px;
      padding: 8px 12px;
      box-shadow: 0 1px 2px rgba(0,0,0,0.15);
      cursor: grab;
      font-size: 14px;
      line-height: 1.4;
      word-break: break-word;
      position: relative;
      transition: opacity 0.15s, transform 0.15s;
    }

    .card:hover {
      background: #f4f5f7;
    }

