      font-size: 14px;
      line-height: 1.4;
      word-break: break-word;
      position: relative;
      transition: opacity 0.15s, transform 0.15s;
    }

    .card:hover {
      background: #f4f5f7;
    }

    .card.dragging {
      opacity: 0.5;
