    .add-card-cancel {
      display: none;
      margin-top: 4px;
      font-size: 13px;
      color: #5e6c84;
      cursor: pointer;
      padding: 4px 0;
    }

    .add-card-cancel:hover {
      color: #172b4d;
    }

    .drop-placeholder {
      background: rgba(0, 121, 191, 0.1);
