  // If dropping directly on the board, find the nearest column
  if (target === boardEl || target.closest('.board') === boardEl) {
    const firstColumn = boardEl.querySelector('.column');
    if (firstColumn) {
      return firstColumn.querySelector('.cards-list');
    }
  }

  return null;
}

// --- SSE Connection ---
function connectSSE() {
  if (sse) {
    sse.close();
