    if (reconnectTimer) {
      clearTimeout(reconnectTimer);
      reconnectTimer = null;
    }
  };

  sse.onerror = () => {
    setStatus('disconnected', 'Reconnecting...');
    // EventSource will auto-reconnect, but track it
    reconnectTimer = setTimeout(connectSSE, 3000);
