    const board = [];
    for (const col of columns) {
      const { rows: cards } = await db.query(
        'SELECT * FROM cards WHERE column_id = $1 ORDER BY position',
        [col.id]
      );
      board.push({
        ...col,
        cards: cards.map(c => ({ ...c, column_id: col.id }))
      });
