    'SELECT c.*, col.id as column_id FROM cards c JOIN columns col ON c.column_id = col.id WHERE c.column_id = $1 ORDER BY c.position',
    [columnId]
  );
  broadcast('renormalize', { columnId, cards: updatedCards });
}

