function generateId() {
  return crypto.randomUUID();
}

function mid(a, b) {
  if (a === undefined && b === undefined) return 0.5;
  if (a === undefined) return b + 0.5;
  if (b === undefined) return a - 0.5;
  return (a + b) / 2;
}

